function drawPikachuPopMart(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.3;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 3.5;

  const tailLag = breathPhase - 0.45;
  const tailSwayX = Math.sin(tailLag) * 5.0;
  const tailSwayY = Math.cos(tailLag) * 3.0;

  // Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 26 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // Đuôi sấm sét
  const tx = 16 + tailSwayX;
  const ty = by - 8 + tailSwayY;
  ctx.fillStyle = '#78350f';
  ctx.beginPath(); ctx.roundRect(8, by + 16, 8, 4, 2); ctx.fill();
  ctx.fillStyle = '#facc15';
  ctx.beginPath(); ctx.moveTo(tx - 4, ty + 16); ctx.lineTo(tx + 6, ty + 12); ctx.lineTo(tx + 2, ty + 22); ctx.fill();
  ctx.beginPath(); ctx.moveTo(tx + 4, ty + 12); ctx.lineTo(tx + 14, ty + 2); ctx.lineTo(tx + 8, ty + 16); ctx.fill();
  ctx.beginPath(); ctx.moveTo(tx + 10, ty + 4); ctx.lineTo(tx + 28, ty - 24); ctx.lineTo(tx + 14, ty - 8); ctx.fill();

  // Thân vàng & chân
  ctx.fillStyle = '#facc15';
  ctx.beginPath(); ctx.ellipse(0, by + 14, 20 * sX, 18 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(-14, by + 27, 8, 9, 4); ctx.fill();
  ctx.beginPath(); ctx.roundRect(6, by + 27, 8, 9, 4); ctx.fill();

  // Đầu vàng
  ctx.beginPath(); ctx.ellipse(0, by - 8, 22 * sX, 18 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // Tai vàng chóp đen
  ctx.beginPath(); ctx.moveTo(-13, by - 19); ctx.lineTo(-25, by - 42); ctx.lineTo(-7, by - 22); ctx.fill();
  ctx.beginPath(); ctx.moveTo(7, by - 22); ctx.lineTo(30, by - 36); ctx.lineTo(13, by - 18); ctx.fill();
  ctx.fillStyle = '#0f172a';
  ctx.beginPath(); ctx.moveTo(-20, by - 32); ctx.lineTo(-25, by - 42); ctx.lineTo(-15, by - 35); ctx.fill();
  ctx.beginPath(); ctx.moveTo(20, by - 30); ctx.lineTo(30, by - 36); ctx.lineTo(22, by - 24); ctx.fill();

  // Má đỏ
  ctx.fillStyle = '#ef4444';
  ctx.beginPath(); ctx.arc(-16, by + 1, 6, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(16, by + 1, 6, 0, Math.PI * 2); ctx.fill();

  // Mắt đen
  if (!blink) {
    ctx.fillStyle = '#0f172a';
    ctx.beginPath(); ctx.ellipse(-10, by - 8, 4, 6, 0, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(10, by - 8, 4, 6, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-11, by - 11, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(9, by - 11, 2, 0, Math.PI * 2); ctx.fill();
  }

  // Miệng cười
  ctx.fillStyle = '#881337';
  ctx.beginPath(); ctx.moveTo(0, by + 8); ctx.lineTo(-6, by + 1); ctx.lineTo(6, by + 1); ctx.fill();
  ctx.fillStyle = '#f472b6';
  ctx.beginPath(); ctx.arc(0, by + 6, 3, 0, Math.PI * 2); ctx.fill();

  // Tay nhỏ
  ctx.fillStyle = '#facc15';
  ctx.beginPath(); ctx.arc(-12, by + 12, 4, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(12, by + 12, 4, 0, Math.PI * 2); ctx.fill();

  ctx.restore();
}
